        + *(play_game_vec2_t *)&ui_element_slot_11.vertices[0].x;
    tutorial_button.label = "Tutorial";
    position += play_game_vec2_t(330.0f, 50.0f);
    position.x += ui_element_slot_11.render_offset_x - 64.0f;
    float base_position[2] = {position.x, position.y};

    grim_interface_ptr->grim_bind_texture(
        texture_handles.ui_item_texts_texture, 0);
    grim_interface_ptr->grim_set_uv(0.0f, 0.125f, 1.0f, 0.25f);
    grim_interface_ptr->grim_set_config_var(0x15, 1u);
    grim_interface_ptr->grim_draw_quad(
        position.x - 64.0f,
        position.y - 8.0f,
        128.0f,
        32.0f);
    grim_interface_ptr->grim_end_batch();
    grim_interface_ptr->grim_set_config_var(0x15, 2u);
    grim_interface_ptr->grim_set_color(1.0f, 1.0f, 1.0f, 1.0f);

    bool show_play_counts = false;
    if (grim_interface_ptr->grim_is_key_down(0x3b)) {
        show_play_counts = true;
        grim_interface_ptr->grim_draw_text_small_fmt(
            position.x + 132.0f,
            position.y + 16.0f,
            "times played:");
    }

    bool roomy_layout =
        quest_unlock_index < 0x28 || config_player_count > 1;
    if (roomy_layout) {
        position.y += 32.0f;
        if (mode_play_rush + quest_play_counts[11] + mode_play_survival <= 0) {
            if (config_player_count == 1) {
                ui_button_update(
                    (float *)&position, (ui_button_t *)&tutorial_button);
            }
            position.y += 32.0f;
        }

        ui_button_update((float *)&position, (ui_button_t *)&quests_button);
        if (show_play_counts) {
            grim_interface_ptr->grim_draw_text_small_fmt(
                position.x + 158.0f,
                position.y + 8.0f,
                "%d",
                play_game_quest_count());
        }
        position.y += 32.0f;

        ui_button_update((float *)&position, (ui_button_t *)&rush_button);
        if (show_play_counts) {
            grim_interface_ptr->grim_draw_text_small_fmt(
                position.x + 158.0f,
                position.y + 8.0f,
                "%d",
                mode_play_rush);
        }
        position.y += 32.0f;

        ui_button_update((float *)&position, (ui_button_t *)&survival_button);
        if (show_play_counts) {
            grim_interface_ptr->grim_draw_text_small_fmt(
                position.x + 158.0f,
                position.y + 8.0f,
                "%d",
                mode_play_survival);
        }
        position.y += 32.0f;

        if (quest_play_counts[11] + mode_play_survival + mode_play_rush > 0) {
            if (config_player_count == 1) {
                ui_button_update(
                    (float *)&position, (ui_button_t *)&tutorial_button);
            }
            position.y += 32.0f;
        }
    } else {
        position.y += 26.0f;
        if (quest_play_counts[11] + mode_play_survival + mode_play_rush <= 0) {
            if (config_player_count == 1) {
                ui_button_update(
                    (float *)&position, (ui_button_t *)&tutorial_button);
            }
            position.y += 28.0f;
        }

        ui_button_update((float *)&position, (ui_button_t *)&quests_button);
        if (show_play_counts) {
            grim_interface_ptr->grim_draw_text_small_fmt(
                position.x + 158.0f,
                position.y + 8.0f,
                "%d",
                play_game_quest_count());
        }
        position.y += 28.0f;

        ui_button_update((float *)&position, (ui_button_t *)&rush_button);
        if (show_play_counts) {
            grim_interface_ptr->grim_draw_text_small_fmt(
                position.x + 158.0f,
                position.y + 8.0f,
                "%d",
                mode_play_rush);
        }
        position.y += 28.0f;

        ui_button_update((float *)&position, (ui_button_t *)&survival_button);
        if (show_play_counts) {
            grim_interface_ptr->grim_draw_text_small_fmt(
                position.x + 158.0f,
                position.y + 8.0f,
                "%d",
                mode_play_survival);
        }
        position.y += 28.0f;

        if (game_is_full_version()) {
            if (config_player_count == 1) {
                ui_button_update(
                    (float *)&position, (ui_button_t *)&typo_button);
            }
            if (show_play_counts) {
                grim_interface_ptr->grim_draw_text_small_fmt(
                    position.x + 158.0f,
                    position.y + 8.0f,
                    "%d",
                    mode_play_typo);
            }
        }
        position.y += 28.0f;

        if (quest_play_counts[11] + mode_play_survival + mode_play_rush > 0) {
            ui_button_update(
                (float *)&position, (ui_button_t *)&tutorial_button);
            position.y += 28.0f;
        }
    }

    char *player_count_labels[4] = {
        "1 player", "2 players", "3 players", "4 players"
    };
    static play_game_list_t player_count_list;
    player_count_list.items = player_count_labels;
    player_count_list.selected_index = config_player_count - 1;
    player_count_list.item_count = 2;

    grim_interface_ptr->grim_set_color(1.0f, 1.0f, 1.0f, 0.81f);
    play_game_vec2_t list_position(base_position[0] + 80.0f, base_position[1] + 1.0f);
    int selected = ui_list_widget_update(
        (float *)&list_position, (ui_list_widget_t *)&player_count_list);
    if (selected > -2
        && (input_primary_just_pressed()
            || grim_interface_ptr->grim_was_key_pressed(0x1c))) {
        player_count_list.open = 1 - player_count_list.open;
        if (selected >= 0) {
            player_count_list.selected_index = selected;
            config_player_count = selected + 1;
            highscore_load_table_thunk();
        }

