    float alpha;
    bool force_small;
    bool force_wide;
    unsigned char padding_tail[2];

    play_game_button_t()
    {
        enabled = true;
        force_wide = false;
        force_small = false;
        alpha = 1.0f;
        click_anim = 0;
        label = 0;
